// Application kits: tailored resume + cover letter per job (generated by the worker).
import fs from 'node:fs';
import { Router } from 'express';
import mongoose from 'mongoose';
import { z } from 'zod';
import {
  JobModel,
  llmEnabled,
  TailoredDocModel,
  TaskModel,
  toTailoredDocDto,
  type TailoredDocDto,
} from '@ja/shared';
import { HttpError, parse } from '../http.js';

export const docsRouter = Router();

const ACTIVE = { $in: ['pending', 'running'] };

/** Queues a tailoring task unless one is already waiting for this job. Returns the task id. */
export async function enqueueTailor(
  jobId: string,
  trigger: 'manual' | 'shortlist',
): Promise<string> {
  const active = await TaskModel.findOne({
    type: 'tailor_job',
    'payload.jobId': jobId,
    status: ACTIVE,
  }).lean();
  if (active) return String(active._id);
  const task = await TaskModel.create({
    type: 'tailor_job',
    payload: { jobId, trigger },
    maxAttempts: 2,
  });
  return String(task._id);
}

docsRouter.get('/jobs/:id/docs', async (req, res) => {
  if (!mongoose.isValidObjectId(req.params.id)) throw new HttpError(400, 'Invalid id');
  const [latest, task] = await Promise.all([
    TailoredDocModel.findOne({ jobId: req.params.id }).sort({ version: -1 }).lean(),
    TaskModel.findOne({
      type: 'tailor_job',
      'payload.jobId': req.params.id,
      status: ACTIVE,
    }).lean(),
  ]);
  const body: { latest: TailoredDocDto | null; pendingTaskId?: string; llmEnabled: boolean } = {
    latest: latest ? toTailoredDocDto(latest) : null,
    pendingTaskId: task ? String(task._id) : undefined,
    llmEnabled: llmEnabled(),
  };
  res.json(body);
});

docsRouter.post('/jobs/:id/tailor', async (req, res) => {
  const job = await JobModel.findById(req.params.id, { _id: 1 }).lean();
  if (!job) throw new HttpError(404, 'Job not found');
  if (!llmEnabled()) throw new HttpError(409, 'Generating resumes needs ANTHROPIC_API_KEY in .env');
  res.status(202).json({ taskId: await enqueueTailor(String(job._id), 'manual') });
});

docsRouter.get('/docs/:id/resume.pdf', async (req, res) => {
  const doc = await TailoredDocModel.findById(req.params.id).lean();
  if (!doc?.resumePdfPath || !fs.existsSync(doc.resumePdfPath))
    throw new HttpError(404, 'PDF not found');
  const job = await JobModel.findById(doc.jobId, { company: 1 }).lean();
  const name = String((doc.resume as { name?: string } | undefined)?.name ?? 'Resume').replace(
    /\s+/g,
    '_',
  );
  const company = (job?.company ?? 'job').replace(/[^\w]+/g, '_').replace(/^_|_$/g, '');
  res.download(doc.resumePdfPath, `${name}_Resume_${company}.pdf`);
});

const DocPatch = z.object({ coverLetter: z.string().trim().min(20).max(5000) }).strict();

docsRouter.patch('/docs/:id', async (req, res) => {
  const { coverLetter } = parse(DocPatch, req.body);
  const doc = await TailoredDocModel.findByIdAndUpdate(
    req.params.id,
    { $set: { coverLetter, coverLetterEdited: true } },
    { new: true },
  ).lean();
  if (!doc) throw new HttpError(404, 'Document not found');
  res.json(toTailoredDocDto(doc));
});
